main.addEventListener('input',e=>{if(e.target.id==='booking-search'){query=e.target.value;const position=e.target.selectionStart;render();const input=document.querySelector('#booking-search');input.focus();input.setSelectionRange(position,position)}if(e.target.id==='yen-amount')document.querySelector('#converted').textContent=money(Math.max(0,Number(e.target.value)||0)*model.info.exchange)});
document.querySelector('#import-file').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>5*1024*1024){toast('La copia è troppo grande. Limite: 5 MB.');return}try{const imported=validate(JSON.parse(await file.text()));confirm('Importare questo programma?',`Contiene ${imported.days.length} giornate e ${imported.reservations.length} prenotazioni. Sostituirà il programma su questo dispositivo; puoi annullare dal menu.`,()=>change(()=>{model=imported;selected=0},'Programma importato'))}catch(error){toast(error.message||'Non riesco a leggere questa copia del programma.')}};
