function svg(name){return `<svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${SYMBOLS[name]||SYMBOLS.pin}</svg>`}
function japanClock(now=new Date()){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now),get=t=>parts.find(p=>p.type===t).value;return {date:`${get('year')}-${get('month')}-${get('day')}`,time:`${get('hour')}:${get('minute')}`}}
function todayIndex(){return model.days.findIndex(d=>d.date===japanClock().date)}
function cityArt(day){const title=day.title.toLowerCase(),city=(day.to||day.from).toLowerCase();if(/fuji|kawag/.test(title)||/kawag|fuji/.test(city))return {key:'fuji',name:'Monte Fuji',y:1202,h:334};if(/kanazawa/.test(title)||/kanazawa/.test(city))return {key:'kanazawa',name:'Kanazawa',y:615,h:307};if(/takayama|kamikochi/.test(title)||/takayama/.test(city))return {key:'takayama',name:'Takayama',y:923,h:278};if(/kyoto/.test(title)||/kyoto/.test(city))return {key:'kyoto',name:'Kyoto',y:307,h:307};return {key:'tokyo',name:/roma/.test(day.from.toLowerCase())?'Si parte':/kamakura/.test(title)?'Tokyo e dintorni':'Tokyo',y:0,h:307}}
function transportMeta(e){if(e.kind!=='trasporto')return '';const first=e.title.split(/\r?\n/)[0],duration=first.match(/\b\d+(?:[.,:]\d+)?\s*(?:min(?:uti)?|m\b|h\b)/i)?.[0],fare=first.match(/\b\d+(?:[.,]\d+)?\s*[¥€]|[¥€]\s*\d+(?:[.,]\d+)?/i)?.[0];const route=eventTitle(e);return [duration,fare].filter(v=>v&&!route.includes(v)).map(v=>esc(v.replace(/m$/,' min'))).join(' · ')}
function coverHTML(day,small=false){const art=cityArt(day);return `<div class="city-cover ${small?'small-cover':''}" data-city="${art.key}"><svg class="cover-art" viewBox="0 ${art.y} 1024 ${art.h}" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustrazione originale di ${art.name}"><image width="1024" height="1536" href="${window.JAPAN_COVERS||''}"/></svg><div class="cover-shade"></div><div class="cover-copy"><span class="cover-kicker">IL NOSTRO GIAPPONE · AUTUNNO 2026</span><strong>${esc(art.name)}</strong><span>${dateText(day.date,true)}${day.to&&day.to!==day.from?' · Verso '+esc(day.to):''}</span></div></div>`}
function eventTitle(e){const lines=e.title.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(e.kind==='trasporto'){const route=lines.find(s=>/➡|→|⇄/.test(s));if(route)return route.replace(/^[^\p{L}\p{N}]+/u,'').slice(0,105);if(/line|\bmin\b|\b\d+m\b|stop/i.test(lines[0]||''))return (lines[0]||'Spostamento').replace(/^[^\p{L}\p{N}]+/u,'').slice(0,90)}return (lines[0]||'Attività').length>95?lines[0].slice(0,92)+'…':lines[0]||'Attività'}
function eventHTML(e,day){const b=model.reservations.find(b=>b.id===e.bookingId),title=eventTitle(e),detailed=e.title!==title||!!e.notes||e.links.length>1,types={attivita:['pin','Da vedere'],trasporto:['train','Spostamento'],pasto:['food','A tavola'],nota:['info','Da sapere']};const [symbol,kind]=types[e.kind];const map=e.links.find(u=>/maps/.test(u));const primary=map?link(map,'Apri mappa','map-link'):mapSearch(e,day);return `<article class="event kind-${e.kind} ${e.done?'done':''}" data-event="${esc(e.id)}"><div class="event-time">${esc(e.time||'Libero')}</div><div class="event-card"><div class="event-type"><span class="event-symbol">${svg(symbol)}</span><span class="kind-label">${kind}</span>${b?chip(b):''}</div><div class="event-title-row"><h3>${esc(title)}</h3><button class="check-event" data-action="done" data-id="${esc(e.id)}" aria-label="${e.done?'Segna come da fare':'Segna come completata'}: ${esc(title)}" aria-pressed="${e.done}">${e.done?svg('check'):''}</button></div>${transportMeta(e)?`<div class="transport-meta">${transportMeta(e)}</div>`:''}${detailed?`<details class="event-details"><summary>${e.kind==='trasporto'?'Indicazioni e cambi':'Leggi dettagli'} <span>⌄</span></summary><div class="details-body">${e.title!==title?`<p>${esc(e.title)}</p>`:''}${e.notes?`<p>${esc(e.notes)}</p>`:''}<div class="event-bottom">${linksHTML(e.links.filter(u=>u!==map))}</div></div></details>`:''}<div class="event-bottom">${primary}${!detailed?linksHTML(e.links.filter(u=>u!==map)):''}${/^(pranzo|cena) a\s*$/i.test(e.title)?'<span class="chip pending">Locale da scegliere</span>':''}</div>${editing?`<div class="event-actions"><button data-action="edit-event" data-id="${esc(e.id)}">Modifica o sposta</button><button data-action="delete-event" data-id="${esc(e.id)}">Elimina</button></div>`:''}</div></article>`}
function dayHTML(day,index,printing=false){const b=model.reservations.find(b=>b.id===day.hotel),warnings=model.warnings.filter(w=>w.dayId===day.id);const events=[...day.events].sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));return `<section class="day-content ${printing?'print-day':''}"><div class="day-top"><span class="eyebrow">Giorno ${String(index+1).padStart(2,'0')} · ${dateText(day.date)}</span>${printing?'':`<div class="day-pager"><button data-action="prev-day" aria-label="Giorno precedente" ${index===0?'disabled':''}>‹</button><button data-action="next-day" aria-label="Giorno successivo" ${index===model.days.length-1?'disabled':''}>›</button></div>`}</div><div class="day-heading"><h1>${esc(day.title)}</h1><p class="day-subtitle">${esc(day.from)}${day.to&&day.to!==day.from?' · Notte a '+esc(day.to):''}</p>${editing?`<button class="edit-day" data-action="edit-day" data-id="${esc(day.id)}">Modifica giornata</button>`:''}</div>${b?`<div class="stay-card"><div class="stay-icon">${svg('moon')}</div><div><small>Questa sera dormiamo qui</small><strong>${esc(b.title)}</strong></div>${b.links[0]?link(b.links[0],'Mappa','stay-map'):''}</div>`:''}${day.notes?`<details class="day-notes"><summary>Note della giornata</summary><p>${esc(day.notes)}</p></details>`:''}${warnings.length?`<details class="day-alerts"><summary>${svg('info')} ${warnings.length===1?'Un dettaglio da verificare':warnings.length+' dettagli da verificare'} <span>⌄</span></summary>${warnings.map(w=>`<div class="notice"><div>${esc(w.text)}</div>${editing?`<button data-action="dismiss-warning" data-id="${esc(w.id)}">Risolto</button>`:''}</div>`).join('')}</details>`:''}<div class="timeline-head"><h2>La nostra giornata <span>${events.length} tappe</span></h2>${editing?`<button class="primary" data-action="add-event" data-id="${esc(day.id)}">+ Aggiungi</button>`:`<span>${events.filter(e=>e.done).length}/${events.length} fatte</span>`}</div><div class="timeline">${events.length?events.map(e=>eventHTML(e,day)).join(''):'<div class="empty">Una giornata tutta da inventare. Attiva Modifica per aggiungere le attività.</div>'}</div></section>`}
function dayRail(){return `<aside class="day-list" aria-label="Giornate del viaggio"><span class="rail-label">LE NOSTRE TAPPE</span>${model.days.map((d,i)=>`<button class="day-button ${i===selected?'selected':''} ${d.date===japanClock().date?'is-today':''}" data-action="select-day" data-index="${i}" ${i===selected?'aria-current="date"':''}><span class="day-number">${String(i+1).padStart(2,'0')}</span><span><span class="day-city">${esc(d.from)}</span><span class="day-date">${dateText(d.date)}</span></span></button>`).join('')}</aside>`}
