function overviewHTML(){return `<div class="page-heading"><span class="eyebrow">DAL 28 OTTOBRE AL 12 NOVEMBRE</span><h1>Il viaggio, tutto insieme.</h1><p>Da Tokyo alle montagne, passando per Kyoto. Scegli una giornata per aprire il programma.</p></div><div class="overview-grid">${model.days.map((d,i)=>`<button class="overview-card" data-action="open-overview-day" data-index="${i}">${coverHTML(d,true)}<div class="overview-copy"><span class="eyebrow">GIORNO ${String(i+1).padStart(2,'0')} · ${dateText(d.date)}</span><strong>${esc(d.title)}</strong><span>${d.events.filter(e=>e.kind==='attivita').length} visite · ${d.events.length} voci ${svg('arrow')}</span></div></button>`).join('')}</div>`}
function todayHTML(){const clock=japanClock(),index=todayIndex();if(index<0){const start=model.days[0].date,remaining=Math.ceil((Date.parse(start+'T00:00:00Z')-Date.parse(clock.date+'T00:00:00Z'))/86400000);return `${coverHTML(model.days[Math.min(1,model.days.length-1)])}<div class="today-intro"><span class="eyebrow">LA NOSTRA PROSSIMA AVVENTURA</span><h1>${remaining>0?'Il Giappone ci aspetta.':'Un viaggio da ricordare.'}</h1><p>${remaining>0?'Mancano '+remaining+' giorni alla partenza. Durante il viaggio qui troverai la giornata corrente, seguendo l’ora del Giappone.':'Il viaggio è terminato. Tutte le giornate rimangono nel programma.'}</p><button class="primary" data-action="open-program">Esplora il programma ${svg('arrow')}</button><button class="secondary" data-action="overview">Vedi tutte le tappe</button></div><div class="pretrip-grid"><div><strong>${model.days.length}</strong><span>giorni insieme</span></div><div><strong>5</strong><span>grandi tappe</span></div><div><strong>${model.reservations.filter(b=>b.status==='booked').length}</strong><span>prenotazioni confermate</span></div></div>`}
const day=model.days[index],events=[...day.events].sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99')),next=events.find(e=>!e.done&&e.time&&e.time>=clock.time),b=model.reservations.find(b=>b.id===day.hotel),pending=events.map(e=>model.reservations.find(b=>b.id===e.bookingId)).filter(b=>b&&b.status!=='booked');return `${coverHTML(day)}<div class="today-heading"><div><span class="eyebrow">OGGI IN GIAPPONE · ${clock.time}</span><h1>${esc(day.title)}</h1></div><button class="secondary" data-action="open-overview-day" data-index="${index}">Giornata completa ${svg('arrow')}</button></div><div class="today-grid"><section class="next-activity"><span class="eyebrow">${next?'PROSSIMA TAPPA PREVISTA':'IL RESTO DELLA GIORNATA'}</span>${next?`<div class="next-time">${esc(next.time)}</div><h2>${esc(eventTitle(next))}</h2><p>Orario del programma, da adattare ai nostri tempi.</p><div class="event-bottom">${next.links.find(u=>/maps/.test(u))?link(next.links.find(u=>/maps/.test(u)),'Apri mappa','map-link'):mapSearch(next,day)}</div>`:'<h2>Godiamoci la serata.</h2><p>Consulta la giornata completa per le attività libere o quelle ancora da fare.</p>'}</section><section class="today-stay"><span class="eyebrow">${svg('moon')} QUESTA SERA</span><h2>${esc(b?.title||day.to||'In viaggio')}</h2>${b?.links[0]?link(b.links[0],'Apri la mappa dell’alloggio','map-link'):''}<p>${events.filter(e=>e.done).length} di ${events.length} attività segnate come fatte su questo telefono.</p></section></div>${pending.length?`<div class="notice"><div><strong>Da organizzare oggi:</strong> ${pending.map(b=>esc(b.title)).join(', ')}.</div></div>`:''}<div class="timeline-head"><h2>Le tappe di oggi</h2><span>Ora del Giappone</span></div><div class="timeline">${events.filter(e=>e.kind==='attivita'||e.kind==='pasto').map(e=>eventHTML(e,day)).join('')}</div>`}
function infoHTML(){let original=baseInfoHTML();const at=original.indexOf('<section class="info-card wide"><h2>Il programma');if(at>=0)original=original.slice(0,at)+'<section class="info-card wide"><h2>Il programma del gruppo</h2><p>Roberto e Leonardo preparano le attività nell’area Gestione e le pubblicano per tutti. Gli aggiornamenti arrivano all’apertura e ogni minuto mentre l’app è online, dopo la pubblicazione del sito.</p><p>Le spunte delle attività fatte restano personali. Offline rimane l’ultima versione ricevuta.</p><p class="sync-description"></p><div class="info-actions"><button class="primary" data-program-refresh>Aggiorna programma</button><button class="secondary" data-action="export">Esporta una copia</button><button class="secondary" data-action="import">Importa una bozza</button></div><p>Per gli organizzatori: <a href="gestione.html">apri Gestione</a> · <a href="guida-gestione.html" target="_blank" rel="noopener">guida ai due accessi</a>.</p><p>Su iPhone: Safari → Condividi → Aggiungi alla schermata Home.</p></section></div>';return original}

function render(){selected=Math.max(0,Math.min(selected,model.days.length-1));rememberView();main.className='view-'+view;main.innerHTML=(editing&&!['moments','more'].includes(view)?'<div class="editing-banner">Modifica personale attiva · Esporta una copia per conservarla.</div>':'')+({program:programHTML,today:todayHTML,overview:overviewHTML,moments:window.JAPAN_MOMENTS.render,more:moreHTML,bookings:bookingsHTML,budget:budgetHTML,info:infoHTML}[view]||programHTML)();document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view||(view==='overview'&&b.dataset.view==='program')||(['budget','info'].includes(view)&&b.dataset.view==='more');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.querySelector('#pending-count').textContent=model.reservations.filter(b=>b.status!=='booked').length;document.querySelector('#edit-toggle').textContent=feedUrl?'Apri foglio':editing?'Fine modifica':'Modifica';document.querySelector('#edit-toggle').setAttribute('aria-pressed',editing);updateSyncBadge();if(model.updatedAt)document.querySelector('#footer-date').textContent='Programma aggiornato: '+new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short'}).format(new Date(model.updatedAt));window.JAPAN_MOMENTS.onView(view==='moments',sharedAppUrl());document.querySelector("#edit-toggle").hidden=["moments","more"].includes(view);window.JAPAN_PROGRAM_SHARED?.paint();}

function moreHTML(){return '<div class="page-heading"><span class="eyebrow">TUTTO QUELLO CHE SERVE</span><h1>In viaggio, senza pensieri.</h1><p>Le spese, i consigli utili e il collegamento al programma condiviso.</p></div><div class="more-cards"><button class="more-card" data-view="budget">'+svg('wallet')+'<strong>Budget</strong><span>Quanto costa il viaggio e come si dividono le spese.</span></button><button class="more-card" data-view="info">'+svg('info')+'<strong>Info e strumenti</strong><span>Consigli, numeri utili e aggiornamento dal foglio Google.</span></button></div>'}
window.JAPAN_NAV_ICONS=Object.fromEntries(Object.keys(SYMBOLS).map(key=>[key,svg(key)]));window.JAPAN_NAV_ICONS.camera=window.JAPAN_MOMENTS.icon("camera");window.JAPAN_NAV_ICONS.more=window.JAPAN_MOMENTS.icon("more");

// Read-only shared itinerary. Local edits and completion ticks are never sent to Google.
const FEED_KEY=KEY+'-feed',REMOTE_KEY=KEY+'-remote',DONE_KEY=KEY+'-done',REMOTE_BACKUP_KEY=KEY+'-before-sync',UI_KEY=KEY+'-view';
let feedUrl='',syncState='local',lastSync=null,syncBusy=false,doneState={};
function allowedFeed(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.hostname!=='script.google.com'||!/^\/macros\/s\/[\w-]+\/exec$/.test(u.pathname))return '';u.search='';u.hash='';return u.href}catch{return ''}}
try{doneState=JSON.parse(localStorage.getItem(DONE_KEY)||'{}');if(!doneState||Array.isArray(doneState)||typeof doneState!=='object')doneState={};feedUrl=allowedFeed(localStorage.getItem(FEED_KEY)||'');const shared=new URL(location.href).searchParams.get('feed');if(shared){const accepted=allowedFeed(shared);if(accepted){feedUrl=accepted;localStorage.setItem(FEED_KEY,feedUrl)}}if(feedUrl){const cached=localStorage.getItem(REMOTE_KEY);if(cached){model=validate(JSON.parse(cached));lastSync=model.updatedAt;applyDone();syncState='cached';}else syncState='waiting';}}catch{syncState='local'}
function eventKey(event,day){return day.date+'|'+event.time+'|'+event.title}
function rememberView(){try{localStorage.setItem(UI_KEY,JSON.stringify({view,date:model.days[selected]?.date}))}catch{}}
function applyDone(){for(const day of model.days)for(const event of day.events){const key=eventKey(event,day);if(Object.prototype.hasOwnProperty.call(doneState,key))event.done=doneState[key]===true}}
function rememberDone(){for(const day of model.days)for(const event of day.events)doneState[eventKey(event,day)]=event.done;try{localStorage.setItem(DONE_KEY,JSON.stringify(doneState))}catch{}}
function syncDescription(){if(!feedUrl)return 'Collegamento non ancora attivato. Stai consultando la copia salvata sul tuo telefono.';if(syncState==='busy')return 'Sto controllando il foglio Google…';if(syncState==='error')return 'Non riesco ad aggiornare ora. Rimane disponibile l’ultima copia ricevuta.';if(!navigator.onLine)return 'Sei offline. Stai consultando l’ultima copia salvata.';return 'Foglio collegato'+(lastSync?' · Ultimo controllo '+new Intl.DateTimeFormat('it-IT',{hour:'2-digit',minute:'2-digit'}).format(new Date(lastSync)):' · Primo aggiornamento da completare');}
function updateSyncBadge(){if(window.JAPAN_PROGRAM_SHARED?.installed){window.JAPAN_PROGRAM_SHARED.paint();return;}const badge=document.querySelector('#save-state');if(!badge)return;badge.textContent=feedUrl?(syncBusy?'Aggiornamento…':!navigator.onLine?'Copia offline':syncState==='error'?'Copia salvata':'Foglio collegato'):model.updatedAt?'Copia personale':'Programma pronto';badge.title=syncDescription();}
function readFeed(url){return new Promise((resolve,reject)=>{const name='japanFeed_'+Date.now()+'_'+Math.random().toString(36).slice(2),script=document.createElement('script');let timer;function cleanup(){clearTimeout(timer);delete window[name];script.remove()}window[name]=value=>{cleanup();resolve(value)};script.onerror=()=>{cleanup();reject(new Error('Il collegamento Google non risponde. Controlla che l’app web sia accessibile a chiunque.'))};script.src=url+'?callback='+name+'&t='+Date.now();script.referrerPolicy='no-referrer';timer=setTimeout(()=>{cleanup();reject(new Error('Google non ha risposto. Verifica l’indirizzo e l’accesso al servizio.'))},25000);document.head.append(script)});}
async function syncNow(manual=false){if(window.JAPAN_PROGRAM_SHARED?.ownsProgram())return window.JAPAN_PROGRAM_SHARED.refresh(manual);if(!feedUrl){if(manual)openSyncSetup();return}if(syncBusy||document.hidden||!navigator.onLine){updateSyncBadge();if(manual&&!navigator.onLine)toast('Sei offline: il programma salvato resta disponibile.');return}syncBusy=true;syncState='busy';updateSyncBadge();try{const response=await readFeed(feedUrl);if(response?.error)throw new Error(response.error);if(window.JAPAN_PROGRAM_SHARED?.ownsProgram())return;const incoming=validate(response.program?JAPAN_SHEET_PARSER.parse(response,seed):response),selectedDate=model.days[selected]?.date;rememberDone();const changed=JSON.stringify({...incoming,updatedAt:null})!==JSON.stringify({...model,updatedAt:null});model=incoming;applyDone();selected=Math.max(0,model.days.findIndex(d=>d.date===selectedDate));lastSync=new Date().toISOString();syncState='ready';try{localStorage.setItem(REMOTE_KEY,JSON.stringify(model))}catch{storageIssue('Il programma è aggiornato, ma non riesco a conservarlo offline. Esporta una copia.')}if(changed){const y=scrollY;render();scrollTo(0,y)}if(manual)toast('Programma aggiornato dal foglio Google')}catch(error){syncState='error';if(manual)toast(error.message||'Aggiornamento non riuscito.')}finally{syncBusy=false;updateSyncBadge();const description=document.querySelector('.sync-description');if(description)description.textContent=syncDescription();}}
function sharedAppUrl(){const u=new URL(location.href);u.search='';u.hash='';if(feedUrl&&!window.JAPAN_PROGRAM_SHARED?.ownsProgram())u.searchParams.set('feed',feedUrl);return u.href}
function openSyncSetup(){const dialog=document.querySelector('#sync-setup');document.querySelector('#sync-feed-url').value=feedUrl;document.querySelector('#sync-setup-error').textContent='';document.querySelector('#sync-current-link').textContent=feedUrl?sharedAppUrl():'';document.querySelector('#sync-current-link').hidden=!feedUrl;document.querySelector('#disconnect-sync').hidden=!feedUrl;dialog.showModal();}
document.querySelector('#save-sync').onclick=async()=>{const value=allowedFeed(document.querySelector('#sync-feed-url').value.trim());if(!value){document.querySelector('#sync-setup-error').textContent='Incolla l’indirizzo dell’app web Google che termina con /exec.';return}if(!feedUrl&&model.updatedAt){try{localStorage.setItem(REMOTE_BACKUP_KEY,JSON.stringify(model))}catch{}downloadBackup('Giappone_prima_del_collegamento');}feedUrl=value;syncState='waiting';editing=false;try{localStorage.setItem(FEED_KEY,feedUrl)}catch{}document.querySelector('#sync-setup').close();render();await syncNow(true);if(syncState==='ready')toast('Foglio collegato. Condividi con gli amici il link aggiornato dal menu.');};
document.querySelector('#disconnect-sync').onclick=()=>confirm('Usare una copia personale?','Il programma attuale rimane su questo telefono. Le nuove modifiche del foglio non arriveranno finché non lo ricolleghi.',()=>{feedUrl='';syncState='local';try{localStorage.removeItem(FEED_KEY);localStorage.setItem(KEY,JSON.stringify(model))}catch{}const url=new URL(location.href);url.searchParams.delete('feed');history.replaceState(null,'',url);document.querySelector('#sync-setup').close();render();toast('Ora puoi modificare la tua copia personale.');});
document.querySelector('#copy-shared-link').onclick=async()=>{const url=sharedAppUrl();try{await navigator.clipboard.writeText(url);toast('Link copiato: mandalo al gruppo WhatsApp.')}catch{document.querySelector('#sync-current-link').hidden=false;document.querySelector('#sync-current-link').textContent=url;toast('Seleziona e copia il collegamento mostrato.')}};
document.querySelector('#sync-close').onclick=()=>document.querySelector('#sync-setup').close();
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='done')rememberDone();if(action==='go-today'){view='today';render();scrollTo({top:0,behavior:'smooth'})}if(action==='overview'){view='overview';render();scrollTo({top:0,behavior:'smooth'})}if(action==='open-program'){view='program';render();scrollTo({top:0,behavior:'smooth'})}if(action==='open-overview-day'){selected=Number(el.dataset.index);view='program';render();scrollTo({top:0,behavior:'smooth'})}if(action==='configure-sync')openSyncSetup();if(action==='sync-now')syncNow(true);});
document.querySelector('#edit-toggle').onclick=()=>{if(window.JAPAN_PROGRAM_SHARED?.ownsProgram()){if(window.JAPAN_PROGRAM_SHARED.admin&&!window.JAPAN_PROGRAM_SHARED.busy){editing=!editing;render();}return;}if(feedUrl){window.open(model.sourceUrl,'_blank','noopener,noreferrer');return}editing=!editing;render();toast(editing?'Modifica la tua copia personale':'Modifica conclusa')};
// A shared feed owns the itinerary. Imports require explicitly leaving shared mode.
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(feedUrl&&!window.JAPAN_PROGRAM_SHARED?.ownsProgram()&&button&&['import','reset','undo'].includes(button.dataset.action)){event.preventDefault();event.stopImmediatePropagation();toast('Prima scollega il foglio per usare una copia personale.')}},true);
window.addEventListener('online',()=>syncNow());window.addEventListener('offline',()=>{updateSyncBadge();if(view==='info')render()});document.addEventListener('visibilitychange',()=>{if(!document.hidden){syncNow();const index=todayIndex();if(view==='today')render()}});
try{const previous=JSON.parse(localStorage.getItem(UI_KEY)||'null');if(previous&&['program','today','overview','bookings','budget','info','moments','more'].includes(previous.view)){view=previous.view;const index=model.days.findIndex(d=>d.date===previous.date);if(index>=0)selected=index}}catch{}
const currentDay=todayIndex();if(currentDay>=0){selected=currentDay;view='today'}
setInterval(()=>{if(!document.hidden){syncNow();if(view==='today'&&!syncBusy)render()}},60000);
setTimeout(()=>syncNow(),150);

if(location.hash.includes('momenti='))view='moments';
window.JAPAN_PROGRAM_SHARED?.install({
 validate,get:()=>clone(model),view:()=>view,isEditing:()=>editing,toast,confirm,
 set:p=>{const date=model.days[selected]?.date;model=validate(p);applyDone();selected=Math.max(0,model.days.findIndex(d=>d.date===date));undoStack=[]},
 setEditing:value=>{editing=value},rememberDone,render
});
document.addEventListener('click',event=>{if(event.target.closest('[data-program-refresh]'))window.JAPAN_PROGRAM_SHARED.refresh(true)});
render();if(location.protocol==='https:'&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
